package main

import (
	"bytes"
	"os"
	"path/filepath"
	"testing"
)

func TestCLI_ArgumentParsing(t *testing.T) {
	tests := []struct {
		name       string
		args       []string
		wantExit   int
		wantStderr string
	}{
		{"no args", []string{}, 2, "Usage:"},
		{"unknown command", []string{"bogus"}, 2, "unknown command"},
		{"get without key", []string{"get"}, 2, "requires a key"},
		{"set without value", []string{"set", "key"}, 2, "requires key and value"},
		{"delete without key", []string{"delete"}, 2, "requires a key"},
		{"flags only no command", []string{"--quiet", "--verbose"}, 2, "no command specified"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			stdout, stderr := &bytes.Buffer{}, &bytes.Buffer{}
			cli := NewCLI(stdout, stderr, t.TempDir())

			got := cli.Run(tt.args)
			if got != tt.wantExit {
				t.Errorf("exit code = %d, want %d", got, tt.wantExit)
			}
			if !bytes.Contains(stderr.Bytes(), []byte(tt.wantStderr)) {
				t.Errorf("stderr = %q, want containing %q", stderr.String(), tt.wantStderr)
			}
		})
	}
}

func TestCLI_Init(t *testing.T) {
	t.Run("creates config file", func(t *testing.T) {
		stdout, stderr := &bytes.Buffer{}, &bytes.Buffer{}
		tmpDir := t.TempDir()
		cli := NewCLI(stdout, stderr, tmpDir)

		exit := cli.Run([]string{"init"})
		if exit != 0 {
			t.Fatalf("exit = %d, stderr = %s", exit, stderr.String())
		}

		configPath := filepath.Join(tmpDir, "config.yaml")
		if _, err := os.Stat(configPath); os.IsNotExist(err) {
			t.Error("config file not created")
		}
	})

	t.Run("fails if exists", func(t *testing.T) {
		stdout, stderr := &bytes.Buffer{}, &bytes.Buffer{}
		tmpDir := t.TempDir()
		cli := NewCLI(stdout, stderr, tmpDir)

		cli.Run([]string{"init"})
		exit := cli.Run([]string{"init"})
		if exit != 1 {
			t.Errorf("exit = %d, want 1", exit)
		}
	})
}

func TestCLI_SetGetDelete(t *testing.T) {
	stdout, stderr := &bytes.Buffer{}, &bytes.Buffer{}
	tmpDir := t.TempDir()
	cli := NewCLI(stdout, stderr, tmpDir)

	cli.Run([]string{"init"})

	// Set
	stdout.Reset()
	if exit := cli.Run([]string{"set", "mykey", "myvalue"}); exit != 0 {
		t.Fatalf("set failed: %s", stderr.String())
	}

	// Get
	stdout.Reset()
	if exit := cli.Run([]string{"get", "mykey"}); exit != 0 {
		t.Fatalf("get failed: %s", stderr.String())
	}
	if got := stdout.String(); got != "myvalue\n" {
		t.Errorf("get = %q, want %q", got, "myvalue\n")
	}

	// Delete
	stdout.Reset()
	if exit := cli.Run([]string{"delete", "mykey"}); exit != 0 {
		t.Fatalf("delete failed: %s", stderr.String())
	}

	// Get after delete should fail
	stderr.Reset()
	if exit := cli.Run([]string{"get", "mykey"}); exit != 1 {
		t.Error("get after delete should fail")
	}
}

func TestCLI_OutputFormats(t *testing.T) {
	formats := []struct {
		format   string
		contains string
	}{
		{"text", "testkey: testval"},
		{"json", `"testkey"`},
		{"yaml", "testkey:"},
	}

	for _, tt := range formats {
		t.Run(tt.format, func(t *testing.T) {
			stdout, stderr := &bytes.Buffer{}, &bytes.Buffer{}
			tmpDir := t.TempDir()
			cli := NewCLI(stdout, stderr, tmpDir)

			cli.Run([]string{"init"})
			cli.Run([]string{"set", "testkey", "testval", "--quiet"})
			stdout.Reset()

			cli.Run([]string{"list", "--format", tt.format})
			if !bytes.Contains(stdout.Bytes(), []byte(tt.contains)) {
				t.Errorf("output = %q, want containing %q", stdout.String(), tt.contains)
			}
		})
	}
}

func TestCLI_InvalidYAML(t *testing.T) {
	stdout, stderr := &bytes.Buffer{}, &bytes.Buffer{}
	tmpDir := t.TempDir()
	configPath := filepath.Join(tmpDir, "config.yaml")

	os.WriteFile(configPath, []byte("{{invalid yaml"), 0644)

	cli := NewCLI(stdout, stderr, tmpDir)
	exit := cli.Run([]string{"validate"})

	if exit != 1 {
		t.Errorf("exit = %d, want 1", exit)
	}
	if !bytes.Contains(stderr.Bytes(), []byte("invalid YAML")) {
		t.Errorf("stderr = %q, want YAML error", stderr.String())
	}
}
